import{_ as t,o,c as a,a4 as n}from"./chunks/framework.DCsBdTIw.js";const u=JSON.parse('{"title":"OpenCode","description":"Connect OpenCode to Tokeness through CC Switch or an OpenAI-compatible configuration.","frontmatter":{"title":"OpenCode","description":"Connect OpenCode to Tokeness through CC Switch or an OpenAI-compatible configuration."},"headers":[],"relativePath":"integrations/opencode.md","filePath":"integrations/opencode.md","lastUpdated":1784332800000}'),i={name:"integrations/opencode.md"};function s(d,e,l,r,h,p){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="opencode" tabindex="-1">OpenCode <a class="header-anchor" href="#opencode" aria-label="Permalink to &quot;OpenCode&quot;">​</a></h1><p>OpenCode supports multiple models and custom providers. When connecting to Tokeness, choose OpenAI Compatible and fill in the Tokeness Base URL, API key, and model name.</p><p>When you manage OpenCode configuration through <a href="https://ccswitch.io/zh/docs?section=getting-started" target="_blank" rel="noreferrer">CC Switch</a>, Claude Code, Codex, and OpenCode can all switch providers from the same tool.</p><h2 id="connection-details" tabindex="-1">Connection details <a class="header-anchor" href="#connection-details" aria-label="Permalink to &quot;Connection details&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Provider</td><td><code>OpenAI Compatible</code> or custom</td></tr><tr><td>Name</td><td><code>Tokeness</code></td></tr><tr><td>Base URL</td><td><code>https://n.tokeness.dev/v1</code></td></tr><tr><td>API Key</td><td>A key created in the Tokeness console</td></tr><tr><td>Model</td><td>Copied from the Tokeness model marketplace</td></tr></tbody></table><h2 id="_1-prepare-tokeness" tabindex="-1">1. Prepare Tokeness <a class="header-anchor" href="#_1-prepare-tokeness" aria-label="Permalink to &quot;1. Prepare Tokeness&quot;">​</a></h2><p>In the Tokeness console:</p><ol><li>Confirm the wallet balance is available.</li><li>Create an API key dedicated to OpenCode.</li><li>Copy a model name from the model marketplace.</li><li>Open the usage logs — you will use them later to verify requests.</li></ol><p>You can name the key:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>opencode-local</span></span></code></pre></div><h2 id="_2-install-opencode" tabindex="-1">2. Install OpenCode <a class="header-anchor" href="#_2-install-opencode" aria-label="Permalink to &quot;2. Install OpenCode&quot;">​</a></h2><p>Install OpenCode using the official method. A common install command is:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://opencode.ai/install</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span></span></code></pre></div><p>After installation, confirm the command is available:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">opencode</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>If the system reports the command cannot be found, close the terminal and reopen it, or check the PATH configuration mentioned by the install script.</p><h2 id="_3-configure-through-cc-switch" tabindex="-1">3. Configure through CC Switch <a class="header-anchor" href="#_3-configure-through-cc-switch" aria-label="Permalink to &quot;3. Configure through CC Switch&quot;">​</a></h2><ol><li>Open CC Switch.</li><li>Switch to <code>OpenCode</code> on the left.</li><li>Click the <code>+</code> button in the top right.</li><li>Choose <code>OpenAI Compatible</code> as the preset. If that preset is not available, choose custom.</li><li>Set the name to <code>Tokeness</code>.</li><li>Enter your Tokeness API key.</li><li>Set the Base URL to <code>https://n.tokeness.dev/v1</code>.</li><li>Enter the full model name from the Tokeness model marketplace.</li><li>Save and enable.</li></ol><p>If the interface supports a connection test, click it once after saving. If the test fails, check the key, Base URL, and model name first.</p><h2 id="_4-field-mapping-for-manual-configuration" tabindex="-1">4. Field mapping for manual configuration <a class="header-anchor" href="#_4-field-mapping-for-manual-configuration" aria-label="Permalink to &quot;4. Field mapping for manual configuration&quot;">​</a></h2><p>If you are not using CC Switch, fill in the fields in OpenCode&#39;s own provider settings according to the mapping below:</p><table tabindex="0"><thead><tr><th>OpenCode field</th><th>Tokeness value</th></tr></thead><tbody><tr><td>Provider Type</td><td>OpenAI Compatible</td></tr><tr><td>API Key</td><td>Tokeness API key</td></tr><tr><td>Base URL / Endpoint</td><td><code>https://n.tokeness.dev/v1</code></td></tr><tr><td>Model</td><td>Tokeness model name</td></tr></tbody></table><p>Do not select the Anthropic provider. The Tokeness general endpoint uses the OpenAI-compatible format.</p><h2 id="_5-launch-and-verify" tabindex="-1">5. Launch and verify <a class="header-anchor" href="#_5-launch-and-verify" aria-label="Permalink to &quot;5. Launch and verify&quot;">​</a></h2><p>Close the current terminal, reopen one, and run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">opencode</span></span></code></pre></div><p>Enter:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Please reply with a single sentence confirming OpenCode is connected to Tokeness.</span></span></code></pre></div><p>Then check the Tokeness usage logs to confirm the request record.</p><h2 id="_6-model-switching" tabindex="-1">6. Model switching <a class="header-anchor" href="#_6-model-switching" aria-label="Permalink to &quot;6. Model switching&quot;">​</a></h2><p>OpenCode is well suited to configuring multiple models at once. You can split them by purpose:</p><table tabindex="0"><thead><tr><th>Configuration</th><th>Purpose</th></tr></thead><tbody><tr><td>Coding model</td><td>Writing code, fixing bugs, generating tests</td></tr><tr><td>Reasoning model</td><td>Complex problem analysis, architecture design</td></tr><tr><td>Low-cost model</td><td>Document cleanup, bulk renaming, simple Q&amp;A</td></tr></tbody></table><p>After switching models, if OpenCode does not pick up the change immediately, exit OpenCode and re-enter.</p><h2 id="_7-troubleshooting" tabindex="-1">7. Troubleshooting <a class="header-anchor" href="#_7-troubleshooting" aria-label="Permalink to &quot;7. Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Fix</th></tr></thead><tbody><tr><td>OpenCode cannot find the provider</td><td>Confirm CC Switch has saved and enabled Tokeness</td></tr><tr><td>401 Unauthorized</td><td>Re-copy the API key</td></tr><tr><td>404 Not Found</td><td>Set Base URL to <code>https://n.tokeness.dev/v1</code></td></tr><tr><td>model not found</td><td>Re-copy the model name from the model marketplace</td></tr><tr><td>Auto-fetch model list failed</td><td>Fill in the model name manually</td></tr><tr><td>No Tokeness logs</td><td>OpenCode is not using the Tokeness provider; check the currently enabled configuration</td></tr><tr><td>Still on the old model after switching</td><td>Exit OpenCode and reopen the terminal</td></tr></tbody></table>',35)])])}const m=t(i,[["render",s]]);export{u as __pageData,m as default};
